/**
 * Build an array of indentation strings, where shift[n] is the prefix used at
 * nesting level n (each level adds one `step`). Index 0 is always "\n".
 *
 * @param {number|string} step - Number of spaces per indentation level
 *        (1-12, mapped to the corresponding space string) or an arbitrary
 *        string to use directly as the indent unit.
 * @returns {string[]} Array of "\n" + n times the indent unit.
 */
function createShiftArr(step) {
	var space = "    ";

	if (isNaN(parseInt(step))) {
		// argument is string
		space = step;
	} else {
		// argument is integer
		switch (step) {
			case 1:
				space = " ";
				break;
			case 2:
				space = "  ";
				break;
			case 3:
				space = "   ";
				break;
			case 4:
				space = "    ";
				break;
			case 5:
				space = "     ";
				break;
			case 6:
				space = "      ";
				break;
			case 7:
				space = "       ";
				break;
			case 8:
				space = "        ";
				break;
			case 9:
				space = "         ";
				break;
			case 10:
				space = "          ";
				break;
			case 11:
				space = "           ";
				break;
			case 12:
				space = "            ";
				break;
		}
	}

	var shift = ["\n"]; // array of shifts
	for (ix = 0; ix < 100; ix++) {
		shift.push(shift[ix] + space);
	}
	return shift;
}

/**
 * vkbeautify formatter constructor. Holds the indentation unit (4 spaces by
 * default) and the pre-computed shift array used during formatting.
 *
 * @constructor
 */
function vkbeautify() {
	this.step = "    "; // 4 spaces
	this.shift = createShiftArr(this.step);
}

//----------------------------------------------------------------------------
/**
 * 统一关键字大写表：sql() 管线中所有需要强制大写的关键字/函数名。
 * 遍历在字符串与注释已替换为占位符之后进行（词边界匹配不会命中占位符内部），
 * 短语按空白匹配（\s+），排序后长短语优先，避免前缀误吞。
 * 仅靠本表即可完成大写，replace_char 只保留带换行/空格副作用的归一规则。
 */
var KEYWORD_TABLE = [
	// 连接
	"LEFT SEMI JOIN", "LEFT OUTER JOIN", "RIGHT OUTER JOIN", "FULL OUTER JOIN",
	"INNER JOIN", "LEFT JOIN", "RIGHT JOIN", "FULL JOIN", "CROSS JOIN",
	"LATERAL VIEW", "ADD JAR", "MAPJOIN",
	// 子句与短语
	"GROUP BY", "ORDER BY", "PARTITION BY", "DISTRIBUTE BY", "SORT BY",
	"CLUSTER BY", "GROUPING SETS", "INSERT OVERWRITE", "INSERT INTO",
	"IF NOT EXISTS", "IF EXISTS", "IS NOT NULL", "IS NULL", "CURRENT ROW",
	// 关键字
	"SELECT", "FROM", "WHERE", "HAVING", "LIMIT", "UNION", "INTERSECT",
	"EXCEPT", "WITH", "DISTINCT", "AS", "AND", "OR", "NOT", "IN", "EXISTS",
	"BETWEEN", "LIKE", "RLIKE", "IS", "JOIN", "INNER", "LEFT", "RIGHT",
	"FULL", "OUTER", "CROSS", "SEMI", "ON", "USING", "CASE", "WHEN", "THEN",
	"ELSE", "END", "OVER", "ROWS", "RANGE", "UNBOUNDED", "PRECEDING",
	"FOLLOWING", "OVERWRITE", "INTO", "VALUES", "TABLE", "PARTITION", "VIEW",
	"CREATE", "ALTER", "DROP", "TRUNCATE", "DELETE", "SET", "ASC", "DESC",
	// 窗口与函数
	"ROW_NUMBER", "DENSE_RANK", "RANK", "LAG", "LEAD", "NTILE", "EXPLODE",
	"SPLIT", "MAP_KEYS", "ARRAY", "CONCAT", "GET_JSON_OBJECT",
	"REGEXP_REPLACE", "NVL", "COALESCE", "CAST", "IF", "ROUND", "CEIL",
	"FLOOR", "DATEDIFF", "DATE_FORMAT", "TO_DATE", "UNIX_TIMESTAMP",
	"FROM_UNIXTIME", "MOD", "MAX", "MIN", "SUM", "AVG", "COUNT",
	// 日期时间
	"CURRENT_DATE", "CURRENT_TIMESTAMP", "INTERVAL", "DATE", "TIMESTAMP",
];

var KEYWORD_RE = (function () {
	var sources = KEYWORD_TABLE.map(function (kw) {
		return kw.split(/ +/).join("\\s+");
	});
	sources.sort(function (a, b) {
		var wa = a.split(/\\s\+/).length;
		var wb = b.split(/\\s\+/).length;
		if (wa != wb) {
			return wb - wa;
		}
		return b.length - a.length;
	});
	return new RegExp("\\b(?:" + sources.join("|") + ")\\b", "gi");
})();

/**
 * 关键字表驱动的统一大写遍历：按词边界（多词短语按 \s+ 连接）匹配
 * KEYWORD_TABLE 并整体转为大写。调用时机在 replace_char 之后、get_bracket
 * 之前，此时字符串/普通注释均为占位符，不会误伤其内部文本；优化器提示
 * （/*+ ... *\/）内的关键字按惯例仍参与大写。紧邻 "." 的词视为点分
 * 标识符的一部分（如 SET 配置键 hive.exec.dynamic.partition），不改写。
 *
 * @param {string} text - 已完成空格与换行归一的文本。
 * @returns {string} 关键字全部大写后的文本。
 */
function uppercase_keywords(text) {
	return text.replace(KEYWORD_RE, function (m, offset, s) {
		var before = offset > 0 ? s.charAt(offset - 1) : "";
		var after = s.charAt(offset + m.length);
		if (before == "." || after == ".") {
			return m;
		}
		return m.toUpperCase();
	});
}

//----------------------------------------------------------------------------
/**
 * Step 1 of the pipeline: normalize whitespace and line breaks.
 * Collapses multiple spaces into one, then applies a large set of keyword
 * replacements so that every major SQL keyword (SELECT, FROM, JOIN, WHERE,
 * GROUP BY, ...) is surrounded by a single space or starts a new line.
 * Also normalizes operators ("=", ">", "<", ...) to have consistent spacing.
 * Pure case normalization is NOT done here — the keyword-table pass
 * (uppercase_keywords) is the single authority for that.
 *
 * @param {string} str - Raw SQL text.
 * @returns {string} Text with normalized spacing and keyword line breaks.
 */
function replace_char(str) {
	return (
		str
			.replace(/\n/g, " ")
			.replace(/\s+/gi, " ")
			.replace(/ AND /gi, " AND ")
			.replace(/\nAND /gi, " AND ")
			.replace(/ THEN /gi, " THEN ")
			.replace(/ WHEN /gi, " WHEN ")
			.replace(/INSERT OVERWRITE/gi, "INSERT OVERWRITE")
			.replace(/INSERT INTO/gi, "INSERT INTO")
			.replace(/ BETWEEN /gi, " BETWEEN ")
			.replace(/ CASE WHEN /gi, " CASE WHEN ")
			.replace(/ \,CASE WHEN /gi, " ,CASE WHEN ")
			.replace(/ FROM\(/gi, " FROM (")
			.replace(/ JOIN\(/gi, " JOIN (")
			.replace(/ FROM /gi, "\nFROM ")
			.replace(/ DISTRIBUTE BY /gi, "\nDISTRIBUTE BY ")
			.replace(/ AS /gi, " AS ")
			.replace(/ TABLE /gi, " TABLE ")
			.replace(/ IF EXISTS /gi, " IF EXISTS ")
			.replace(/ HAVING /gi, "\nHAVING ")
			.replace(/ USING /gi, " USING ")
			.replace(/ IN /gi, " IN ")
			.replace(/\(SELECT/gi, "( SELECT")
			.replace(/(^|\s{1,})SELECT /gi, "\nSELECT ")
			.replace(/ WHERE /gi, "\nWHERE ")
			.replace(/ ON /gi, "\nON ")
			.replace(/ JOIN /gi, "\nJOIN ")
			.replace(/ CROSS\nJOIN /gi, "\nCROSS JOIN ")
			.replace(/ INNER\nJOIN /gi, "\nINNER JOIN ")
			.replace(/ LEFT\nJOIN /gi, "\nLEFT JOIN ")
			.replace(/ RIGHT\nJOIN /gi, "\nRIGHT JOIN ")
			// .replace(/ ORDER\s{1,}BY /ig, "\nORDER BY ")
			.replace(/ ORDER\s{1,}BY /gi, " ORDER BY ")
			.replace(/ GROUP\s{1,}BY /gi, "\nGROUP BY ")
			.replace(/ GROUPING\s{1,}SETS/gi, "\nGROUPING SETS")
			.replace(/UNION ALL/gi, "\nUNIONALLALL\n") //先合并unionall避免和union换行发生冲突
			.replace(/(\s|\\n)union(\s|\\n)/gi, "\nUNION \n")
			.replace(/ LEFT OUTER\nJOIN /gi, "\nLEFT OUTER JOIN ")
			.replace(/ RIGHT OUTER\nJOIN /gi, "\nRIGHT OUTER JOIN ")
			.replace(/ FULL OUTER\nJOIN /gi, "\nFULL OUTER JOIN ")
			.replace(/ FULL\nJOIN /gi, "\nFULL JOIN ")
			.replace(/LEFT\s+SEMI\s+JOIN\s?/gi, "\nLEFT SEMI JOIN ")
			.replace(/(^)DROP /gi, "\nDROP ")
			.replace(/(;\s{0,})DROP /gi, ";\nDROP ")
			.replace(/(^| )CREATE /gi, "\nCREATE ")
			.replace(/(^| )INSERT /gi, "\nINSERT ")
			.replace(/(^| )SET /gi, "\nSET ")
			.replace(/(^| )DELETE /gi, "\nDELETE ")
			.replace(/ADD JAR/gi, "ADD JAR")
			.replace(/Alter /gi, "\nALTER ")
			.replace(/WITH /gi, "\nWITH ")
			.replace(/ NOT IN /gi, " NOT IN ")
			.replace(/ LIKE /gi, " LIKE ")
			.replace(/ OVER /gi, " OVER ")
			.replace(/ PARTITION BY /gi, " PARTITION BY ")
			.replace(/\(PARTITION BY /gi, "(PARTITION BY ")
			// --- 新增：目标样式大写规则 ---
			.replace(/(^|\s)CREATE VIEW /gi, "$1CREATE VIEW ")
			.replace(/ CREATE /gi, "\nCREATE ")
			.replace(/ LATERAL VIEW /gi, "\nLATERAL VIEW ")
			.replace(/ TRUNCATE /gi, "\nTRUNCATE ")
			.replace(/ NOT /gi, " NOT ")
			.replace(/ RLIKE /gi, " RLIKE ")
			.replace(/ DISTINCT /gi, " DISTINCT ")
			.replace(/ not in\(/gi, " NOT IN (")
			.replace(/ in\(/gi, " IN (")
			.replace(/ VALUES /gi, " VALUES ")
			.replace(/ INTERSECT(\s|\n)/gi, "\nINTERSECT\n")
			.replace(/ EXCEPT(\s|\n)/gi, "\nEXCEPT\n")
			.replace(/\(ORDER\s{1,}BY /gi, "(ORDER BY ")
			.replace(/ as\(/gi, " AS (")
			.replace(/then\(/gi, "THEN (")
			.replace(/\, ?case/gi, ",CASE")
			.replace(/\(CASE/gi, "(CASE")
			.replace(/ ELSE /gi, " ELSE ")
			.replace(/ END /gi, " END ")
			.replace(/END\)/gi, "END)")
			.replace(/ over\(/gi, " OVER(")
			.replace(/ ROLLUP\(/gi, " ROLLUP(")
			.replace(/ CUBE\(/gi, " CUBE(")
			.replace(/ AS string/gi, " AS STRING")
			.replace(/(^|\s{1,})LIMIT /gi, "\nLIMIT ")
			.replace(/\s{0,}=\s{0,}/gi, " = ") //等号左右强制加空格
			.replace(/! =/gi, "!=")
			.replace(/< =/gi, "<=")
			.replace(/> =/gi, ">=")
			.replace(/: =/gi, ":=") //mysql写法自适应
			.replace(/\s{0,}>\s{0,}/gi, " > ") //大于号左右强制加空格
			.replace(/> =/gi, ">=")
			.replace(/< >/gi, "<>")
			.replace(/\s{0,}<\s{0,}/gi, " < ") //小于号左右强制加空格
			.replace(/< =/gi, "<=")
			.replace(/< >/gi, "<>")
			.replace(/- >/gi, "->")
			.replace(/\s{0,}!=\s{0,}/gi, " != ")
	); //小于等号左右强制加空格
}

/**
 * Step 2 of the pipeline: parse bracket structure so parentheses can be split
 * onto their own lines later. Each "(" and ")" becomes its own line; paired
 * brackets that open a subquery (after JOIN/WITH/FROM, or before a SELECT
 * in IN / EXISTS) are recorded so they are wrapped in newlines by
 * bracket_deep(). Quotes are tracked so that brackets inside string literals
 * are ignored, and the line breaks introduced around quotes are restored at
 * the end.
 *
 * @param {string} str - Text with normalized spacing (output of replace_char).
 * @returns {string} Text where brackets / quotes are on dedicated lines.
 */
function get_bracket(str) {
	var text = str
		.replace(/\(/g, "\n\(")
		.replace(/\)/g, "\n\)")
		.replace(/\'/g, "\n\'");
	text_list_orginal = text.split("\n");
	text_list = [];
	for (i = 0; i < text_list_orginal.length; i++) {
		if (text_list_orginal[i] != "" && text_list_orginal[i] != " ") {
			text_list.push(text_list_orginal[i]);
		}
	}

	var text_final = "";
	var left = [];
	var right = [];
	var bracket = [];
	var bracket_back = [];
	var is_colon = 0;

	for (i = 0; i < text_list.length; i++) {
		last_str = i == 0 ? "" : text_list[i - 1];

		if (text_list[i][0] == "'") {
			if (is_colon == 0) {
				is_colon += 1;
			} else {
				is_colon -= 1;
			}
		}

	if (/\(/gi.exec(text_list[i]) && is_colon == 0) {
		// 加入with as 的判断可能会有坑
		if (
			((/JOIN|WITH/.exec(last_str) ||
				/^\)\s*\,\s*\w+\s+AS/i.exec(last_str) ||
				(/FROM /.exec(last_str) && !/ EXPLODE/gi.exec(last_str))) &&
				!/ORDER BY/.exec(last_str) &&
				!/\/\*/.exec(last_str)) ||
			// IN / EXISTS (SELECT ...) 子查询：括号独立成行，走与 FROM 子查询相同的展开路径
			(/(IN|EXISTS)\s*$/i.test(last_str) &&
				/^SELECT/.test(text_list[i + 1] || ""))) {
			left.push(i);
			bracket.push(i);
			bracket_back.push(1);
		} else {
				// 由于''之间可以随便出现多个中文(号 所以需要过滤一层条件
				bracket.push(i);
				bracket_back.push(0);
			}
		}

		if (/\)/gi.exec(text_list[i]) && is_colon == 0) {
			if (bracket_back[bracket_back.length - 1] == 1) {
				right.push(i);
			}

			bracket = bracket.slice(0, -1);
			bracket_back = bracket_back.slice(0, -1);
		}
	}

	for (i = 0; i < text_list.length; i++) {
		text_list[i] = text_list[i].replace("\n", "");
	}

	for (i = 0; i < left.length; i++) {
		text_list[left[i]] = "\n" + text_list[left[i]];
		text_list[right[i]] = "\n" + text_list[right[i]];
	}

	for (i = 0; i < text_list.length; i++) {
		if (/\(|\)/gi.exec(text_list[i])) {
			text_final += text_list[i];
		} else {
			text_final += "\n" + text_list[i];
		}
	}

	return text_final.replace(/\n\'/gi, "'"); //恢复因为'导致的换行
}

/**
 * Repeat the current string n times (e.g. " ".times(4) === "    ").
 *
 * @param {number} n - Number of repetitions.
 * @returns {string} The string repeated n times.
 */
String.prototype.times = function (n) {
	return new Array(n + 1).join(this);
};

/**
 * Step 3 of the pipeline: apply indentation based on bracket depth.
 * Walks the line list keeping a running depth counter: a line starting with
 * ")" decreases depth (before indenting), a line starting with "(" increases
 * depth (after indenting). Each line is prefixed with depth tabs.
 *
 * @param {string} str - Text whose brackets are on dedicated lines
 *        (output of get_bracket).
 * @returns {string} Text with tab-based indentation by bracket nesting level.
 */
function bracket_deep(str) {
	var text_final = "";
	var text_list = [];
	var text_list_orginal = str.split("\n");
	for (i = 0; i < text_list_orginal.length; i++) {
		if (text_list_orginal[i] != "" && text_list_orginal[i] != " ") {
			text_list.push(text_list_orginal[i]);
		}
	}

	var bracket_deep = 0;
	var deep = "\t";

	for (i = 0; i < text_list.length; i++) {
		if (text_list[i].replace(/\t{0,}/, "")[0] == ")") {
			bracket_deep -= 1;
		}

		text_list[i] = deep.times(bracket_deep) + text_list[i];

		if (text_list[i].replace(/\t{0,}/, "")[0] == "(") {
			bracket_deep += 1;
		}

		text_final += "\n" + text_list[i];
	}
	return text_final;
}

/**
 * Default wrap threshold used when sql() is called without in_wrap_length.
 */
var IN_WRAP_LENGTH_DEFAULT = 150;

/**
 * Measure a line's true rendered length: string placeholders are substituted
 * back via the global restore_list (advancing the given cursor, since
 * placeholders are restored in document order), comment placeholders via
 * comment_list, and tabs count as 4 characters.
 *
 * @param {string} line - The raw line (with placeholders).
 * @param {number} restore_idx - Current position in the global restore_list.
 * @returns {{length: number, restore_idx: number}} Measured length and the
 *          advanced cursor.
 */
function measure_line(line, restore_idx) {
	var substituted = line
		.replace(/NEEDReplace/g, function () {
			var restore_value = restore_list[restore_idx];
			restore_idx += 1;
			return restore_value === undefined ? "NEEDReplace" : restore_value;
		})
		.replace(/(COMMENTPLACEHOLDER|COMMENTBLOCK)(\d+)/g, function (m, p1, p2) {
			var comment_value =
				typeof comment_list !== "undefined"
					? comment_list[Number(p2)]
					: undefined;
			return comment_value === undefined ? m : comment_value;
		})
		.replace(/\t/g, "    ");
	return { length: substituted.length, restore_idx: restore_idx };
}

/**
 * Step 6.5 of the pipeline: wrap overlong IN (...) / NOT IN (...) lists.
 * A line whose formatted length (tabs counted as 4 chars, string/comment
 * placeholders measured at their restored length) exceeds the threshold is
 * rewritten in block style: the keyword stays on the line, "(" gets its own
 * line aligned with the statement, every top-level comma-separated item gets
 * a line of its own (one indent level deeper) and ")" closes the block
 * aligned with "(". Items use leading commas by default, or trailing commas
 * when comma_location is set (emitted directly so every item aligns on the
 * same column).
 *
 * IN lists whose items contain a subquery (SELECT ...) stay on a single
 * line, as do lines shorter than the threshold. in_wrap_length <= 0
 * disables the pass entirely.
 *
 * @param {string} text - Text with bracket-based indentation (output of
 *        bracket_deep).
 * @param {number} in_wrap_length - Max formatted line length before an IN
 *        list is wrapped; <= 0 disables wrapping.
 * @param {boolean} comma_location - Put commas at the end of lines.
 * @returns {string} Text with overlong IN lists wrapped one item per line.
 */
function in_wrap(text, in_wrap_length, comma_location) {
	if (!(in_wrap_length > 0)) {
		return text;
	}

	var text_list_orginal = text.split("\n");
	var text_final_list = [];
	var restore_idx = 0;

	for (let i = 0; i < text_list_orginal.length; i++) {
		var this_line = text_list_orginal[i];
		// 每行都推进占位符游标（还原按文档顺序进行），并用还原后的真实长度测量
		var measured = measure_line(this_line, restore_idx);
		restore_idx = measured.restore_idx;
		if (
			this_line == "" ||
			this_line == " " ||
			measured.length <= in_wrap_length ||
			!/(NOT\s+)?IN\s*\(/i.test(this_line)
		) {
			text_final_list.push(this_line);
			continue;
		}
		text_final_list = text_final_list.concat(
			wrap_in_line(this_line, comma_location),
		);
	}

	return text_final_list.join("\n");
}

/**
 * Rewrite a single overlong line: every IN / NOT IN list on the line is
 * expanded into a block item list (all lists on the line are expanded, not
 * just the first). Text between / after the lists stays on its own line at
 * the original indentation. When any IN list on the line contains a
 * subquery (SELECT) or has no matching closing bracket, the whole line is
 * returned unchanged so subqueries stay on a single line.
 *
 * @param {string} line - The overlong line (tab-indented).
 * @param {boolean} comma_location - Put commas at the end of lines.
 * @returns {string[]} Replacement lines.
 */
function wrap_in_line(line, comma_location) {
	var base_indent = (line.match(/^\t*/) || [""])[0];
	var out_lines = [];
	var cursor = 0;
	var re = /(\bNOT\s+)?\bIN\s*\(/gi;
	var match;

	// 整行预扫描：任一 IN 列表是子查询（或括号不闭合）→ 整行保持原样，
	// 避免只展开其中部分列表把子查询拆散
	var prescan;
	while ((prescan = re.exec(line)) !== null) {
		var pre_close = match_bracket(line, prescan.index + prescan[0].length - 1);
		if (
			pre_close < 0 ||
			/\bSELECT\b/i.test(line.slice(prescan.index + prescan[0].length, pre_close))
		) {
			return [line];
		}
	}

	while ((match = re.exec(line)) !== null) {
		if (match.index < cursor) {
			continue; // 命中在上一个已展开列表内部（嵌套 IN），跳过
		}
		var open_loc = match.index + match[0].length - 1;
		var close_loc = match_bracket(line, open_loc);
		if (close_loc < 0) {
			continue; // 括号不闭合，保持原样
		}
		var inner = line.slice(open_loc + 1, close_loc).trim();
		var items = split_top_comma(inner);
		if (items.length == 0) {
			continue; // 空列表无项可拆，保持原样
		}
		var keyword = match[0].replace(/\s*\($/, "").trim(); // "IN" / "NOT IN"
		var head = line.slice(cursor, match.index).trim();
		if (head != "") {
			out_lines.push(base_indent + head + " " + keyword);
		} else {
			out_lines.push(base_indent + keyword);
		}
		out_lines.push(base_indent + "(");
		for (let q = 0; q < items.length; q++) {
			if (comma_location) {
				// 行尾逗号：直接输出，保证各项列对齐（不依赖 convert_comma_loaction 的逗号搬运）
				out_lines.push(
					base_indent +
						"\t" +
						items[q] +
						(q < items.length - 1 ? "," : ""),
				);
			} else {
				// 前导逗号：首条目多一个空格，使其与后续条目逗号后的值对齐
				out_lines.push(base_indent + "\t" + (q > 0 ? "," : " ") + items[q]);
			}
		}
		out_lines.push(base_indent + ")");
		cursor = close_loc + 1;
	}

	var tail = line.slice(cursor).trim();
	if (tail != "") {
		out_lines.push(base_indent + tail);
	}

	return out_lines;
}

/**
 * Find the index of the ")" matching the "(" at the given position, by
 * bracket counting. At this stage of the pipeline string literals and
 * comments are placeholders without brackets, so bracket counting is
 * sufficient.
 *
 * @param {string} line - The line to scan.
 * @param {number} open_loc - Index of the opening "(".
 * @returns {number} Index of the matching ")", or -1 when unbalanced.
 */
function match_bracket(line, open_loc) {
	var depth = 0;
	for (let p = open_loc; p < line.length; p++) {
		if (line[p] == "(") {
			depth += 1;
		}
		if (line[p] == ")") {
			depth -= 1;
			if (depth == 0) {
				return p;
			}
		}
	}
	return -1;
}

/**
 * Split a comma-separated item list at its top-level commas, ignoring
 * commas nested inside brackets. At this stage of the pipeline string
 * literals and comments are placeholders without brackets, so bracket
 * counting is sufficient. Whole nested expressions (e.g. CASE WHEN ...)
 * remain a single item.
 *
 * @param {string} text - The inner text of an IN (...) list.
 * @returns {string[]} Trimmed items.
 */
function split_top_comma(text) {
	var items = [];
	var current = "";
	var depth = 0;
	for (let p = 0; p < text.length; p++) {
		if (text[p] == "(") {
			depth += 1;
		}
		if (text[p] == ")") {
			depth -= 1;
		}
		if (text[p] == "," && depth == 0) {
			items.push(current.trim());
			current = "";
		} else {
			current += text[p];
		}
	}
	if (current.trim() != "") {
		items.push(current.trim());
	}
	return items;
}

/**
 * Format a CASE WHEN field of a SELECT clause to the target style:
 * the first WHEN stays on the first line, subsequent WHEN conditions are
 * aligned under it, ELSE opens its own line (aligned with CASE) and END AS
 * stays on the same line as ELSE. Lines that start with SELECT (e.g. a
 * nested `THEN (CASE ...)` expression) are left untouched.
 *
 * @param {string} line - A single field line starting with ",CASE".
 * @returns {string} The field re-formatted with aligned WHEN / ELSE.
 */
function format_case_field(line) {
	var when_idx = line.indexOf("WHEN");
	if (when_idx < 0) {
		return "\n" + line;
	}
	var first_when_col = when_idx;
	var parts = line
		.slice(when_idx)
		.split(/\s+(?=WHEN |ELSE |END )/);
	var out = line.slice(0, when_idx) + parts[0];
	for (let i = 1; i < parts.length; i++) {
		var p = parts[i];
		if (/^END /.test(p)) {
			out += " " + p;
		} else if (/^ELSE /.test(p)) {
			out += "\n" + " ".times(8) + p;
		} else {
			out += "\n" + " ".times(first_when_col) + p;
		}
	}
	return "\n" + out;
}

/**
 * Split the body of an OVER (...) window clause into its top-level clauses
 * (PARTITION BY / ORDER BY / ROWS / RANGE ...), ignoring keywords nested in
 * brackets. At this stage of the pipeline string literals and comments are
 * placeholders without brackets, so bracket counting is sufficient.
 *
 * @param {string} text - The inner text of an OVER (...) clause.
 * @returns {string[]} Trimmed clauses (a single element when no split).
 */
function split_window_clauses(text) {
	var depth = 0;
	var depth_at = [];
	for (let p = 0; p < text.length; p++) {
		depth_at[p] = depth;
		if (text[p] == "(") depth += 1;
		if (text[p] == ")") depth -= 1;
	}
	var re = /\b(PARTITION\s+BY|ORDER\s+BY|DISTRIBUTE\s+BY|SORT\s+BY|ROWS|RANGE)\b/gi;
	var starts = [];
	var m;
	while ((m = re.exec(text)) !== null) {
		if (depth_at[m.index] == 0) {
			starts.push(m.index);
		}
	}
	var clauses = [];
	var first = starts.length > 0 ? starts[0] : text.length;
	var head = text.slice(0, first).trim();
	if (head != "") {
		clauses.push(head);
	}
	for (let c = 0; c < starts.length; c++) {
		var end = c + 1 < starts.length ? starts[c + 1] : text.length;
		var piece = text.slice(starts[c], end).trim();
		if (piece != "") {
			clauses.push(piece);
		}
	}
	if (clauses.length == 0) {
		var whole = text.trim();
		return whole == "" ? [] : [whole];
	}
	return clauses;
}

/**
 * Rewrite a single overlong line containing window functions: the first
 * OVER (...) clause with at least two top-level window sub-clauses is
 * expanded in block style — "OVER (" ends the line, every sub-clause gets
 * its own line indented 4 spaces past the start column of the window
 * expression, and ")" returns to the expression start column carrying the
 * text that followed it (e.g. "AS rn"). Indentation is relative to the
 * expression, so comma-aligned select-list columns keep their block inside
 * the column alignment.
 *
 * @param {string} line - The overlong line (tab-indented).
 * @returns {string[]} Replacement lines (the original line when nothing is
 *          expandable).
 */
function wrap_over_in_line(line) {
	var re = /\bOVER\s*\(/gi;
	var match;
	while ((match = re.exec(line)) !== null) {
		var open_loc = match.index + match[0].length - 1;
		var close_loc = match_bracket(line, open_loc);
		if (close_loc < 0) {
			continue;
		}
		var inner = line.slice(open_loc + 1, close_loc).trim();
		var clauses = split_window_clauses(inner);
		if (clauses.length <= 1) {
			continue; // 空子句或单子句（如仅 ORDER BY）不展开
		}
		var leading = (line.match(/^\s*/) || [""])[0];
		var lead_width = leading.replace(/\t/g, "    ").length;
		var expr_col = lead_width + (line.charAt(leading.length) == "," ? 1 : 0);
		var out_lines = [];
		out_lines.push(line.slice(0, match.index) + match[0]);
		for (let q = 0; q < clauses.length; q++) {
			out_lines.push(" ".times(expr_col + 4) + clauses[q]);
		}
		var tail = line.slice(close_loc + 1).trim();
		out_lines.push(
			" ".times(expr_col) + ")" + (tail != "" ? " " + tail : ""),
		);
		return out_lines;
	}
	return [line];
}

/**
 * Step 6.6 of the pipeline: wrap overlong window-function OVER clauses.
 * A line whose formatted length exceeds the threshold and contains an OVER
 * (...) with at least two top-level window sub-clauses is rewritten in
 * block style. Lines that are short enough keep their OVER clause inline.
 *
 * @param {string} text - Text with bracket-based indentation (output of
 *        bracket_deep / in_wrap).
 * @param {number} wrap_length - Max formatted line length before an OVER
 *        clause is wrapped; <= 0 disables the pass.
 * @returns {string} Text with overlong OVER clauses wrapped.
 */
function over_wrap(text, wrap_length) {
	if (!(wrap_length > 0)) {
		return text;
	}

	var text_list_orginal = text.split("\n");
	var text_final_list = [];
	var restore_idx = 0;

	for (let i = 0; i < text_list_orginal.length; i++) {
		var this_line = text_list_orginal[i];
		var measured = measure_line(this_line, restore_idx);
		restore_idx = measured.restore_idx;
		if (
			this_line == "" ||
			this_line == " " ||
			measured.length <= wrap_length ||
			!/\bOVER\s*\(/i.test(this_line)
		) {
			text_final_list.push(this_line);
			continue;
		}
		text_final_list = text_final_list.concat(wrap_over_in_line(this_line));
	}

	return text_final_list.join("\n");
}

/**
 * Split the inner text of a condition group at its top-level connectives.
 * Prefers OR (the looser-binding connective): when any top-level OR is
 * present the text is split at ORs only and AND sub-expressions stay whole;
 * otherwise it is split at top-level ANDs. Keywords nested in brackets are
 * ignored (bracket counting is sufficient at this pipeline stage).
 *
 * @param {string} text - Inner text of a (...) condition group.
 * @returns {{conn: string, parts: string[]}|null} Connective ("OR"/"AND")
 *          and trimmed conditions (none carrying the connective), or null
 *          when there is no top-level connective.
 */
function split_top_connectives(text) {
	var depth = 0;
	var depth_at = [];
	for (var p = 0; p < text.length; p++) {
		depth_at[p] = depth;
		if (text[p] == "(") depth += 1;
		if (text[p] == ")") depth -= 1;
	}
	var re = /\b(OR|AND)\b/gi;
	var or_cuts = [];
	var and_cuts = [];
	var m;
	while ((m = re.exec(text)) !== null) {
		if (depth_at[m.index] == 0) {
			if (m[1].toUpperCase() == "OR") {
				or_cuts.push(m.index);
			} else {
				and_cuts.push(m.index);
			}
		}
	}
	var cuts;
	var conn;
	if (or_cuts.length > 0) {
		cuts = or_cuts;
		conn = "OR";
	} else if (and_cuts.length > 0) {
		cuts = and_cuts;
		conn = "AND";
	} else {
		return null;
	}
	var parts = [];
	var start = 0;
	for (var c = 0; c < cuts.length; c++) {
		parts.push(text.slice(start, cuts[c]).trim());
		start = cuts[c] + conn.length;
	}
	parts.push(text.slice(start).trim());
	if (parts[0] == "") {
		return null; // 畸形输入保险
	}
	return { conn: conn, parts: parts };
}

/**
 * Rewrite a single overlong line containing a parenthesized condition
 * group in block style: the clause keyword stays on its own line, "(" and
 * ")" each get a line aligned with the statement indent, every condition
 * gets its own line one indent level deeper with its OR/AND prefix aligned
 * with the first condition, and any text after ")" moves to its own line.
 * Only the first qualifying group on the line is expanded; a group counts
 * only when the word before "(" is a clause/connective keyword (WHERE /
 * AND / OR / NOT / ON / HAVING / WHEN / THEN / ELSE) or the "(" sits at
 * line start / after another "(", so IN (...), EXISTS (...), IF(...) and
 * function-call parentheses are never touched, nor are subqueries.
 *
 * @param {string} line - The overlong line (tab-indented).
 * @returns {string[]} Replacement lines (the original line when nothing is
 *          expandable).
 */
function wrap_condition_in_line(line) {
	var base_indent = (line.match(/^\t*/) || [""])[0];
	var allow = ["WHERE", "AND", "OR", "NOT", "ON", "HAVING", "WHEN", "THEN", "ELSE"];
	for (var p = 0; p < line.length; p++) {
		if (line[p] != "(") {
			continue;
		}
		var close = match_bracket(line, p);
		if (close < 0) {
			return [line]; // 括号不配对，保持原样
		}
		var before = line.slice(0, p);
		var wm = /([A-Za-z_][A-Za-z0-9_.]*)\s*$/.exec(before);
		if (wm) {
			if (allow.indexOf(wm[1].toUpperCase()) < 0) {
				continue; // 函数名 / IN / EXISTS / IF 等参数括号
			}
		} else {
			var prev_char = before.replace(/\s+$/, "").slice(-1);
			if (prev_char != "" && prev_char != "(") {
				continue; // 行首或嵌套 "(" 之外的位置不视为条件组
			}
		}
		var inner = line.slice(p + 1, close).trim();
		if (/^SELECT\b/i.test(inner)) {
			continue; // 子查询由展开路径负责，此处不拆
		}
		var split = split_top_connectives(inner);
		if (!split || split.parts.length <= 1) {
			continue;
		}
		var head = line.slice(0, p).replace(/\s+$/, "");
		var tail = line.slice(close + 1).trim();
		var out_lines = [];
		if (head != "") {
			out_lines.push(head);
		}
		out_lines.push(base_indent + "(");
		for (var q = 0; q < split.parts.length; q++) {
			var prefix = q == 0 ? "" : split.conn + " ";
			out_lines.push(base_indent + "\t" + prefix + split.parts[q]);
		}
		out_lines.push(base_indent + ")");
		if (tail != "") {
			out_lines.push(base_indent + tail);
		}
		return out_lines;
	}
	return [line];
}

/**
 * Step 6.7 of the pipeline: wrap overlong parenthesized condition groups.
 * A line whose formatted length exceeds the threshold and carries a
 * condition group (see wrap_condition_in_line) is rewritten in block
 * style; short lines keep the group inline. wrap_length <= 0 disables the
 * pass.
 *
 * @param {string} text - Text with bracket-based indentation (output of
 *        bracket_deep / in_wrap / over_wrap).
 * @param {number} wrap_length - Max formatted line length before a
 *        condition group is wrapped; <= 0 disables wrapping.
 * @returns {string} Text with overlong condition groups wrapped.
 */
function condition_wrap(text, wrap_length) {
	if (!(wrap_length > 0)) {
		return text;
	}

	var text_list_orginal = text.split("\n");
	var text_final_list = [];
	var restore_idx = 0;

	for (var i = 0; i < text_list_orginal.length; i++) {
		var this_line = text_list_orginal[i];
		var measured = measure_line(this_line, restore_idx);
		restore_idx = measured.restore_idx;
		if (
			this_line == "" ||
			this_line == " " ||
			measured.length <= wrap_length ||
			!/\(/.test(this_line)
		) {
			text_final_list.push(this_line);
			continue;
		}
		text_final_list = text_final_list.concat(wrap_condition_in_line(this_line));
	}

	return text_final_list.join("\n");
}

/**
 * Format the columns of a SELECT (tag=0) or GROUP BY (tag=1) clause:
 * split top-level commas (ignoring commas inside brackets or quotes) onto
 * their own lines, pretty-print CASE WHEN blocks, and align the "AS"
 * keywords of all columns. Columns longer than as_loc_cnt characters are
 * excluded from AS alignment.
 *
 * @param {string} text - A single clause line (starting with SELECT / GROUP BY).
 * @param {number} tag - 0 for SELECT, 1 for GROUP BY.
 * @param {number} as_loc_cnt - Max column length that still participates in AS alignment.
 * @returns {string} The clause re-formatted with one column per line and aligned AS.
 */
function select_wrap(text, tag, as_loc_cnt) {
	var text_final = "";
	var bracket_cnt = 0;
	var quote_cnt = 0;
	var text_final_case = "";
	var as_loc = 0;
	var max_as_loc = 0;
	var as_loc_list = [];
	var text_as_final = "";
	var text_list = [];

	for (let i = 0; i < text.length; i++) {
		let p = i;
		if (text[p] == "(" && quote_cnt == 0) {
			bracket_cnt += 1;
		}

		if (text[p] == '"' || text[p] == "'") {
			if (quote_cnt == 0) {
				quote_cnt += 1;
			} else {
				quote_cnt -= 1;
			}
		}

		if (text[p] == ")" && quote_cnt == 0) {
			if (bracket_cnt > 0) {
				bracket_cnt -= 1;
			}
		}

		if (bracket_cnt == 0 && quote_cnt == 0 && text[p] == ",") {
			if (tag == 0) {
				text_final += "\n       " + text[p];
			}
			if (tag == 1) {
				text_final += "\n         " + text[p];
			}
		} else {
			text_final += text[p];
		}
	}

	text_final = extract_quotation_mark(text_final); //为了下面case when和as对齐的逻辑，提取引号内容
	text_final = text_final
		.replace(", ", ",")
		.replace("GROUP BY", "GROUP BY ")
		.replace(/\,\s{0,}/gi, ",")
		.replace("SELECT", "SELECT ");
	if (tag == 1) {
		// 锚定行首并归一为两个空格，避免 GROUP BY 分支与 ORDER BY 分支重复追加
		text_final = text_final.replace(/^ORDER BY\s{1,}/, "ORDER BY  ");
	}
	text_final = restore_strmark(text_final); //复原

	text_list = text_final.split("\n");

	// 如果else 和 end 对应上面没有 -- 那么就不再换行，如果有就换行
	if (tag == 0) {
		for (let i = 0; i < text_list.length; i++) {
			if (/\,CASE/.exec(text_list[i])) {
				text_final_case += format_case_field(text_list[i]);
			} else {
				text_final_case += "\n" + text_list[i];
			}
		}
	}

	if (tag == 1) {
		for (let i = 0; i < text_list.length; i++) {
			if (/       \,CASE WHEN/gi.exec(text_list[i])) {
				// console.log(text_list[i]);
				var case_when_list = text_list[i]
					.replace(/WHEN/gi, "\nWHEN")
					.replace(/ELSE/gi, "\nELSE")
					.replace(/\s{1,}END/gi, "\nEND")
					.split("\n");

				var c = 0;
				var if_comment = 0;
				while (c < case_when_list.length) {
					if (c == 0) {
						text_final_case += "\n" + case_when_list[c] + case_when_list[c + 1];
						c += 1;
					} else {
						if (
							(/ELSE/.exec(case_when_list[c]) ||
								/END/.exec(case_when_list[c])) &&
							if_comment == 0
						) {
							text_final_case += " " + case_when_list[c];
						} else {
							text_final_case += "\n             " + case_when_list[c];
						}
					}
					if (case_when_list[c].indexOf("--") > 0) {
						if_comment = 1;
					} else {
						if_comment = 0;
					}
					c += 1;
				}
			} else if (/GROUP BY\s{0,}CASE WHEN/gi.exec(text_list[i])) {
				var case_when_list = text_list[i]
					.replace(/WHEN/gi, "\nWHEN")
					.replace(/ELSE/gi, "\nELSE")
					.replace(/\s{1,}END/gi, "\nEND")
					.split("\n");
				var c = 0;
				var if_comment = 0;
				while (c < case_when_list.length) {
					if (c == 0) {
						text_final_case += "\n" + case_when_list[c] + case_when_list[c + 1];
						c += 1;
					} else {
						if (
							(/ELSE/.exec(case_when_list[c]) ||
								/END/.exec(case_when_list[c])) &&
							if_comment == 0
						) {
							text_final_case += " " + case_when_list[c];
						} else {
							text_final_case += "\n             " + case_when_list[c];
						}
					}
					if (case_when_list[c].indexOf("--") > 0) {
						if_comment = 1;
					} else {
						if_comment = 0;
					}
					c += 1;
				}
			} else {
				text_final_case += "\n" + text_list[i];
			}
		}
	}

	// 让as进行对齐

	text_as_list = text_final_case.split("\n");

	//获取最大的as 的位置
	for (let i = 0; i < text_as_list.length; i++) {
		// 窗口函数/CASE WHEN 字段不参与AS对齐
		if (
			/OVER\(/gi.exec(text_as_list[i]) ||
			/\,CASE/.exec(text_as_list[i]) ||
			/^\s*WHEN |^\s*ELSE /.exec(text_as_list[i])
		) {
			as_loc_list.push(as_loc);
			continue;
		}
		if (/ AS /.exec(text_as_list[i])) {
			as_loc = text_as_list[i].lastIndexOf(" AS ");
			if (as_loc > max_as_loc && as_loc < as_loc_cnt) {
				//150个字符后不再参与as对齐 20211031改成自定义
				max_as_loc = as_loc;
			}
		}
		as_loc_list.push(as_loc);
	}

	//替换as
	for (let i = 0; i < text_as_list.length; i++) {
		// 窗口函数/CASE WHEN 字段不参与AS对齐
		if (
			/OVER\(/gi.exec(text_as_list[i]) ||
			/\,CASE/.exec(text_as_list[i]) ||
			/^\s*WHEN |^\s*ELSE /.exec(text_as_list[i])
		) {
			continue;
		}
		if (/ AS /.exec(text_as_list[i]) && as_loc_list[i] <= max_as_loc) {
			new_as = " ".times(max_as_loc - as_loc_list[i]) + " AS ";
			text_as_list[i] =
				text_as_list[i].slice(0, as_loc_list[i]) +
				text_as_list[i].slice(as_loc_list[i]).replace(" AS ", new_as);
		}
	}

	for (i = 0; i < text_as_list.length; i++) {
		if (text_as_list[i] != "" && text_as_list[i] != " ") {
			text_as_final += text_as_list[i] + "\n";
		}
	}

	return text_as_final;
}

/**
 * Move top-level AND/OR operators (used inside WHERE clauses) onto their own
 * lines, while keeping AND that belongs to BETWEEN, IF(...) or IN(...)
 * expressions on the same line. Tracks bracket depth per token to decide
 * whether an AND is at the top level.
 *
 * @param {string} text - A single WHERE clause line.
 * @returns {string} WHERE clause with each top-level AND starting a new line.
 */
function and_wrap(text) {
	var text_final = "";
	var if_cnt = 0;
	var if_bracket_cnt = 0;
	var bracket_cnt = 0;
	var between_and_cnt = 0;
	text = text
		.replace("IF (", "IF(")
		.replace("IN (", "IN(")
		.replace("if (", "IF(")
		.replace("if(", "IF(");
	text_list = text.split(" ");

	for (let i = 0; i < text_list.length; i++) {
		let t = i;
		last_str = i == 0 ? "" : text_list[i - 1];

		if (/BETWEEN/.exec(text_list[t])) {
			between_and_cnt += 1;
		}

		// 如果and后面本身就跟着括号，等同于存在if(或者in
		if (/IF\(/.exec(text_list[t]) || /IN\(/.exec(text_list[t])) {
			if_cnt += 1;
		}

		if (
			/\(/.exec(text_list[t]) &&
			if_cnt > 0 &&
			text_list[t].indexOf("IF(") == -1 &&
			text_list[t].indexOf("IN(") == -1
		) {
			if_bracket_cnt += 1;
		}

		if (/\)/.exec(text_list[t]) && if_cnt > 0 && if_bracket_cnt > 0) {
			if_bracket_cnt -= 1;
		}

		if (/\)/.exec(text_list[t]) && if_cnt > 0 && if_bracket_cnt == 0) {
			if_cnt -= 1;
		}

		for (let p = 0; p < text_list[t].length; p++) {
			if (/\(/.exec(text_list[t][p])) {
				bracket_cnt += 1;
			}
			if (/\)/.exec(text_list[t][p])) {
				bracket_cnt -= 1;
			}
		}

		if (/^AND$/.exec(text_list[t])) {
			if (between_and_cnt == 0 && if_cnt == 0 && bracket_cnt == 0) {
				text_list[t] = "\n" + text_list[t];
			}
			if (between_and_cnt > 0) {
				between_and_cnt -= 1;
			}
		}
	}

	for (let i = 0; i < text_list.length; i++) {
		let v = i;
		text_final += text_list[v] + " ";
		text_final = text_final.replace("IN(", "IN (");
	}

	return text_final;
}

/**
 * Step 4 of the pipeline: per-line post-processing. Restores quotation marks,
 * then for each non-empty line dispatches to the dedicated clause formatters:
 * SELECT -> select_wrap(0), GROUP BY -> select_wrap(1), WHERE / HAVING ->
 * and_wrap.
 * ORDER BY at the top level of a line is also moved to its own line (brackets
 * are ignored when it appears inside an OVER(...) or aggregate expression).
 *
 * @param {string} text - Text with bracket-based indentation.
 * @param {number} as_loc_cnt - Max column length for AS alignment.
 * @returns {string} Formatted text with protected quotation marks restored.
 */
function special_wrap(text, as_loc_cnt) {
	var text_final = "";
	var text_restore_orginal = restore_strmark(text); //先进行复原成原来样子，此时restore_list重新变为空
	var text_list_orginal = text_restore_orginal.split("\n");
	var text_list = [];
	var new_text_list = [];

	for (i = 0; i < text_list_orginal.length; i++) {
		if (text_list_orginal[i] != "" && text_list_orginal[i] != " ") {
			text_list.push(text_list_orginal[i]);
		}
	}

	//因为对齐的时候需要保持原样
	for (let i = 0; i < text_list.length; i++) {
		let q = i;
		if (text_list[q].slice(0, 6) == "SELECT") {
			//需要部分进行提取再做变化再复原
			text_list[q] = select_wrap(text_list[q], 0, as_loc_cnt);
		}

		if (text_list[q].slice(0, 8) == "GROUP BY") {
			text_list[q] = select_wrap(text_list[q], 1, as_loc_cnt);
		}

		if (text_list[q].slice(0, 5) == "WHERE") {
			text_list[q] = and_wrap(text_list[q]);
		}

		if (text_list[q].slice(0, 6) == "HAVING") {
			text_list[q] = and_wrap(text_list[q]);
		}

		// IN 子查询闭合括号后紧跟的外层 AND 条件拆到新行，与 WHERE 的 AND 风格一致
		if (/^\) AND /.test(text_list[q])) {
			text_list[q] = text_list[q].replace(/^(\) )(AND .*)$/, "$1\n$2");
		}

		//增加order by 换行逻辑
		if (/ORDER BY/gi.exec(text_list[q])) {
			var left_brkt = 0;
			var right_brkt = 0;
			var ordr_loc = text_list[q].indexOf("ORDER BY") + 8;
			var new_str = text_list[q].slice(ordr_loc, -1);
			for (let t = 0; t < new_str.length; t++) {
				if (new_str[t] == "(") {
					left_brkt += 1;
				}
				if (new_str[t] == ")") {
					right_brkt += 1;
				}
			}

			if (right_brkt <= left_brkt) {
				text_list[q] = text_list[q].replace(" ORDER BY ", "\nORDER BY ");
			}
		}

		// 顶层ORDER BY 多列拆分：前导逗号续行 + 双空格对齐
		var ob_loc = text_list[q].indexOf("\nORDER BY");
		if (ob_loc >= 0) {
			text_list[q] =
				text_list[q].slice(0, ob_loc) +
				"\n" +
				select_wrap(text_list[q].slice(ob_loc + 1), 1, as_loc_cnt);
		}

		text_final += "\n" + text_list[q];
	}

	return extract_quotation_mark(text_final);
}

/**
 * Step 5 of the pipeline: merge the content of IN (...) subqueries onto a
 * single line. Every "IN (" start is recorded together with the line index
 * of its matching closing bracket; lines inside such a range are joined with
 * spaces instead of newlines, so `IN (\n ... \n)` collapses to `IN (...)`.
 *
 * @param {string} text - Text with bracket-based indentation.
 * @returns {string} Text where IN-subquery bodies are joined onto one line.
 */
function except_subquery(text) {
	var text_final = "";
	var text_list_orginal = text.split("\n");
	var text_list = [];

	for (i = 0; i < text_list_orginal.length; i++) {
		if (text_list_orginal[i] != "" && text_list_orginal[i] != " ") {
			text_list.push(text_list_orginal[i]);
		}
	}

	var in_bracket_cnt = 0;
	var bracket_cnt = 0;
	var bracket_loc = [];
	var bracket_loc_back = []; //闭

	for (let i = 0; i < text_list.length; i++) {
		if (in_bracket_cnt > 0 && bracket_cnt > 0) {
			for (let p = 0; p < text_list[i].length; p++) {
				if (text_list[i][p] == "(") {
					bracket_cnt += 1;
				}
				if (text_list[i][p] == ")") {
					bracket_cnt -= 1;
					if (bracket_cnt == 0) {
						bracket_loc_back.push(i);
						break;
					}
				}
			}
		}

		if (/IN \($/.exec(text_list[i])) {
			in_bracket_cnt += 1;
			bracket_cnt += 1;
			bracket_loc.push(i);
		}
	}

	for (let i = 0; i < text_list.length; i++) {
		var if_return = 0;
		if (bracket_loc.length > 0) {
			for (let q = 0; q < bracket_loc.length; q++) {
				if (i > bracket_loc[q] && i <= bracket_loc_back[q]) {
					if_return = 1;
					break;
				}
			}

			if (if_return > 0) {
				text_final += " " + text_list[i];
			} else {
				text_final += "\n" + text_list[i];
			}
		} else {
			text_final += "\n" + text_list[i];
		}
	}

	return text_final;
}

// 功能型函数
/**
 * Temporarily replace commas that live inside string literals with full-width
 * commas (，), so that later comma-splitting logic does not break them.
 * The full-width commas are restored at the end of ddl().
 *
 * @param {string} text - DDL text to protect.
 * @returns {string} Text with in-quote commas replaced by full-width commas.
 */
function modify_comma_to_speicific(text) {
	var quote_cnt = 0;
	var quote_tag = "";
	var start_loc = 0;
	var end_loc = 0;
	for (let p = 0; p < text.length; p++) {
		if (text[p] == '"' || text[p] == "'") {
			if (quote_cnt == 0) {
				quote_cnt += 1;
				quote_tag = text[p];
			} else {
				if (text[p] == quote_tag) {
					quote_cnt -= 1;
					end_loc = p;
				}
			}
		} else if (text[p] == "," && quote_cnt != 0) {
			text = text.slice(0, p) + "，" + text.slice(p + 1);
		}
	}
	return text;
}

/**
 * Split a text into top-level comma-separated chunks, ignoring commas inside
 * brackets or quoted literals. Used to split the column list of a CREATE
 * TABLE statement.
 *
 * @param {string} text - Text whose top-level commas separate the parts.
 * @returns {string[]} Array of chunks.
 */
function split_top_level_commas(text) {
	var parts = [];
	var depth = 0;
	var quote = 0;
	var start = 0;
	for (let i = 0; i < text.length; i++) {
		var ch = text[i];
		if (ch == "'" || ch == '"') {
			if (quote == 0) {
				quote = 1;
			} else {
				quote = 0;
			}
			continue;
		}
		if (quote > 0) {
			continue;
		}
		if (ch == "(") {
			depth += 1;
		} else if (ch == ")") {
			depth -= 1;
		} else if (ch == "," && depth == 0) {
			parts.push(text.slice(start, i));
			start = i + 1;
		}
	}
	parts.push(text.slice(start));
	return parts;
}

/**
 * Beautify a Hive CREATE TABLE statement: keep the table name and "(" on the
 * first line, put every column on its own line with aligned names / types /
 * COMMENT clauses (4-space indent, continuation columns prefixed with ","),
 * then emit each trailing clause (COMMENT / PARTITIONED BY / CLUSTERED BY /
 * SORTED BY / ROW FORMAT / STORED AS / TBLPROPERTIES / LOCATION) on its own
 * line in uppercase.
 *
 * @param {string} str - Raw DDL text (CREATE TABLE ...).
 * @returns {string} Aligned, column-per-line DDL text.
 */
function ddl(str) {
	str = modify_comma_to_speicific(str);
	var m =
		/^\s*create\s+(external\s+|temporary\s+)?table\s+((if\s+not\s+exists)\s+)?([^\s(]+)/i.exec(
			str,
		);
	if (!m) {
		return str;
	}
	var prefix =
		"CREATE " +
		(m[1] ? m[1].toUpperCase().trim() + " " : "") +
		"TABLE " +
		(m[2] ? "IF NOT EXISTS " : "") +
		m[4];
	var rest = str.slice(m[0].length);

	var open_idx = rest.indexOf("(");
	if (open_idx < 0) {
		return str;
	}
	var depth = 0;
	var close_idx = -1;
	for (let i = open_idx; i < rest.length; i++) {
		if (rest[i] == "(") {
			depth += 1;
		} else if (rest[i] == ")") {
			depth -= 1;
			if (depth == 0) {
				close_idx = i;
				break;
			}
		}
	}
	if (close_idx < 0) {
		return str;
	}
	var col_list = rest.slice(open_idx + 1, close_idx);
	var tail = rest.slice(close_idx + 1).replace(/;?\s*$/, "").trim();

	var cols = split_top_level_commas(col_list);
	var parsed = [];
	for (let i = 0; i < cols.length; i++) {
		var cm = /^\s*(\S+)\s+(\S+)\s*(?:COMMENT\s*["'](.*?)["'])?\s*$/i.exec(
			cols[i].trim(),
		);
		if (cm) {
			parsed.push({
				name: cm[1],
				type: cm[2].toUpperCase(),
				comment: cm[3] || "",
			});
		}
	}

	if (parsed.length == 0) {
		return prefix + " (" + col_list + ")" + tail + ";";
	}

	var col_len = [];
	var col_type_len = [];
	for (let i = 0; i < parsed.length; i++) {
		col_len.push(parsed[i].name.length);
		col_type_len.push(parsed[i].type.length);
	}
	var max_col_name = Math.max.apply(Math, col_len);
	var max_col_type = Math.max.apply(Math, col_type_len);
	var type_col = 5 + max_col_name + 1;
	var comment_col = type_col + max_col_type + 1;

	var col = "";
	for (let q = 0; q < parsed.length; q++) {
		var name_start = q == 0 ? 4 : 5;
		var name_pad = type_col - name_start - parsed[q].name.length;
		var type_pad = comment_col - type_col - parsed[q].type.length;
		var col_line =
			"    " +
			(q == 0 ? "" : ",") +
			parsed[q].name +
			" ".times(name_pad) +
			parsed[q].type;
		// 未写注释的列不补空 COMMENT ''
		if (parsed[q].comment != "") {
			col_line +=
				" ".times(type_pad) + "COMMENT '" + parsed[q].comment + "'";
		}
		col += col_line.replace(/\s+$/, "") + "\n";
	}

	var clauses = split_tail_clauses(tail);
	var tail_final = "";
	for (let i = 0; i < clauses.length; i++) {
		tail_final +=
			clauses[i]
				.replace(/comment/gi, "COMMENT")
				.replace(/partitioned by/gi, "PARTITIONED BY")
				.replace(/clustered by/gi, "CLUSTERED BY")
				.replace(/sorted by/gi, "SORTED BY")
				.replace(/into (\d+) buckets/gi, "INTO $1 BUCKETS")
				.replace(/row format delimited fields terminated by/gi, "ROW FORMAT DELIMITED FIELDS TERMINATED BY")
				.replace(/stored as/gi, "STORED AS")
				.replace(/tblproperties/gi, "TBLPROPERTIES")
				.replace(/location/gi, "LOCATION")
				.replace(/string/gi, "STRING")
				.replace(/by\(/gi, "BY (")
				.replace(/desc/gi, "DESC")
				.replace(/ orc$/gi, " ORC")
				.replace(/parquet/gi, "PARQUET")
				.replace(/tblproperties\s*\(/gi, "TBLPROPERTIES (")
				.replace(/\s*=\s*/gi, " = ")
				.replace(/\s*，\s*/gi, ", ")
				.replace(/,(?!\s)/g, ", ") + "\n";
	}

	return prefix + " (\n" + col + ")\n" + tail_final + ";";
}

/**
 * Split the tail of a CREATE TABLE statement (everything after the column
 * list) into its top-level clauses, splitting only at whitespace that is
 * outside brackets and followed by a clause keyword. Keyword text inside
 * brackets — e.g. a column COMMENT within PARTITIONED BY (...) — stays on
 * the same line.
 *
 * @param {string} text - Tail text of the CREATE TABLE statement.
 * @returns {string[]} Clause chunks.
 */
function split_tail_clauses(text) {
	var clause_re = /^(COMMENT\b|PARTITIONED\b|CLUSTERED\b|SORTED\b|ROW\b|STORED\b|TBLPROPERTIES\b|LOCATION\b)/i;
	var parts = [];
	var depth = 0;
	var quote = "";
	var start = 0;
	var word_start = -1;
	for (let p = 0; p <= text.length; p++) {
		var ch = p < text.length ? text[p] : " ";
		if (quote != "") {
			if (ch == quote) {
				quote = "";
			}
			continue;
		}
		if (ch == "'" || ch == '"') {
			quote = ch;
			continue;
		}
		if (ch == "(") {
			depth += 1;
			continue;
		}
		if (ch == ")") {
			depth -= 1;
			continue;
		}
		if (depth > 0) {
			continue;
		}
		if (/\s/.test(ch)) {
			if (word_start >= 0) {
				var word = text.slice(word_start, p);
				if (
					clause_re.test(word) &&
					text.slice(start, word_start).trim() != ""
				) {
					parts.push(text.slice(start, word_start).replace(/\s+$/, ""));
					start = word_start;
				}
				word_start = -1;
			}
			continue;
		}
		if (word_start < 0) {
			word_start = p;
		}
	}
	parts.push(text.slice(start).replace(/\s+$/, ""));
	return parts.filter((s) => s.trim() != "");
}

/**
 * Beautify simple DDL statements (ALTER / DROP / TRUNCATE): uppercase the
 * keywords, expand ADD COLUMNS / DROP COLUMNS onto multiple lines with a
 * 4-space indented body, and keep single-line statements on a single line.
 *
 * @param {string} str - Raw DDL text.
 * @returns {string} Beautified DDL text.
 */
function ddl_simple(str) {
	var s = modify_comma_to_speicific(str).replace(/\s+/gi, " ").trim();
	s = s
		.replace(/alter table/gi, "ALTER TABLE")
		.replace(/add columns/gi, "ADD COLUMNS")
		.replace(/drop columns/gi, "DROP COLUMNS")
		.replace(/change column/gi, "CHANGE COLUMN")
		.replace(/drop table/gi, "DROP TABLE")
		.replace(/truncate table/gi, "TRUNCATE TABLE")
		.replace(/if exists/gi, "IF EXISTS")
		.replace(/columns\(/gi, "COLUMNS (")
		.replace(/comment/gi, "COMMENT")
		.replace(/bigint/gi, "BIGINT")
		.replace(/string/gi, "STRING");

	var open = s.indexOf("(");
	var close = s.lastIndexOf(")");
	if (/ADD COLUMNS \(|DROP COLUMNS \(/i.test(s) && open > 0 && close > open) {
		var content = s.slice(open + 1, close).replace(/\s+/gi, " ").trim();
		return s.slice(0, open).trim() + " (\n    " + content + "\n)\n;";
	}
	return s;
}

// 优化有comment的语句
// 几种常见的评论形式
// SELECT a -- comment
// ,b

// SELECT a,
// -- comment
// b,

// SELECT nvl(a,' --'),
// -- comment
// b,

// SELECT nvl(a.xxx,' --') -- comm--e)nt 如果有三个注释符号如果定位到中间一个

// 注释占位符的全局容器：reshape_comment 保护注释，extra 最后恢复
var comment_list = [];
var comment_cnt = 0;

/**
 * Pre-process lines that carry `--` comments so that keywords used inside
 * comments (WHERE, AND, SELECT, ...) cannot be mistaken for real keywords
 * later: they are replaced with placeholder tokens that survive the keyword
 * replacements and are restored in extra(). Also pads ", " after commas that
 * are outside quotes and normalizes comments that start a new line.
 *
 * @param {string} str - Text from the current pipeline stage.
 * @returns {string} Text with comment placeholders and padded commas.
 */
function reshape_comment(str) {
	var text_final = "";
	comment_list = [];
	comment_cnt = 0;
	// 块注释整体保护（/*+ 优化器提示除外，其内部关键字需要被格式化）
	str = str.replace(/\/\*(?!\+)[\s\S]*?\*\//g, function (m) {
		comment_list.push(m);
		return "COMMENTBLOCK" + comment_cnt++;
	});
	// 行注释整体保护：-- 到行尾的内容连同其后换行符一并保护，
	// 避免注释中的关键字/括号/逗号/引号被后续格式化步骤破坏
	str = str.replace(/--[^\n]*(\n|$)/g, function (m, nl) {
		comment_list.push(nl ? m.slice(2, m.length - 1) : m.slice(2));
		return (
			"--COMMENTPLACEHOLDER" + comment_cnt++ + (nl ? "NLMARKER " : "")
		);
	});
	str = str
		//避免关键词注释换行先缩进
		.replace(/\n *\-\-/gi, " \-\-{}");

	var quo_cnt = 0;
	var quo_text = "";
	for (let i = 0; i < str.length; i++) {
		if (str[i] == "'" && quo_cnt == 0) {
			quo_cnt += 1;
		} else if (str[i] == "'" && quo_cnt == 1) {
			quo_cnt -= 1;
		}

		if (quo_cnt == 0 && str[i] == ",") {
			quo_text = quo_text + str[i] + " ";
		} else {
			quo_text += str[i];
		}
	}

	var text_list_orginal = quo_text.split("\n"); // 已知评论不可能和下个字段写在一行

	for (let i = 0; i < text_list_orginal.length; i++) {
		var comment_loc = 0;

		if (text_list_orginal[i] != "" && text_list_orginal[i] != " ") {
			is_comment = text_list_orginal[i].indexOf("--");
			if (is_comment > 0) {
				comment_loc = return_right_comment_loc(text_list_orginal[i]);
			}

			//如果出现SELECT nvl(a.xxx,' --') -- comment"这类，会错误的把commet_loc定位错，所以需要判断所有--符号的位置
			if (is_comment > 0) {
				var a = text_list_orginal[i]
					.slice(0, comment_loc)
					.replace(/\s+/gi, " "); //注释前的东西
				text_list_orginal[i] =
					a.replace(/(\,)\s+$/gi, " ") +
					" " +
					text_list_orginal[i].slice(comment_loc);

				// 注释前的逗号：挪到行注释占位符之后（即注释后的内容边界处），
				// 保证逗号能与后续字段正确拆分，而不是跑到行尾
				if (/\,$/.exec(a.replace(/\s+/gi, ""))) {
					if (text_list_orginal[i].indexOf("NLMARKER") >= 0) {
						text_list_orginal[i] = text_list_orginal[i].replace(
							"NLMARKER",
							"NLMARKER,",
						);
					} else {
						text_list_orginal[i] = text_list_orginal[i] + ",";
					}
				}
			}
			text_final += "\n" + text_list_orginal[i];
		}
	}
	return text_final;
}

/**
 * Final cleanup stage: re-introduce a blank line between independent
 * statements (INSERT / DROP / ALTER / CREATE / SET / SELECT after ";"),
 * trim trailing spaces, strip leading blank lines and comment indentation,
 * normalize ";" placement, and restore all placeholders that were created by
 * earlier stages (UNIONALL, comment keywords, comma braces, ...).
 *
 * @param {string} str - Formatted text.
 * @returns {string} Final cleaned text.
 */
function extra(str) {
	text = str
		.replace(/^\n/gi, "")
		.replace(/UNIONALL/gi, "\nUNION ALL\n")
		.replace(/^ *--/gi, "--")
		.replace(/\s{0,}\;/gi, ";");
	// .replace(/\;\s{0,}INSERT/ig, ";\n\nINSERT")
	// .replace(/\;\s{0,}DROP/ig, ";\n\nDROP");

	var text_final = "";
	var text_list_orginal = str.split("\n");
	var text_list = [];

	for (i = 0; i < text_list_orginal.length; i++) {
		if (text_list_orginal[i] != "" && text_list_orginal[i] != " ") {
			text_list.push(text_list_orginal[i].replace(/\s+$/gi, "")); //剔除行末尾空格
		}
	}

	var is_first_stmt_line = true;
	for (let i = 0; i < text_list.length; i++) {
		var this_line = text_list[i];

		if (i > 0) {
			text_final += "\n";
		}

		// 多行语句的分号单起一行；单行语句（以及带行尾注释的）分号保持在行内
		var semi_idx = this_line.lastIndexOf(";");
		var trailing = semi_idx >= 0 ? this_line.slice(semi_idx + 1) : "";
		var ends_statement =
			semi_idx >= 0 && (trailing.trim() === "" || /^\s*--/.test(trailing));

		if (ends_statement) {
			if (is_first_stmt_line || /^\s*--/.test(trailing)) {
				text_final += this_line;
			} else {
				text_final +=
					this_line.slice(0, semi_idx).replace(/\s+$/, "") + "\n;";
			}
			is_first_stmt_line = true;
		} else {
			if (is_first_stmt_line) {
				is_first_stmt_line = false;
			}
			text_final += this_line;
		}
	}

	return (
		text_final
			.replace(/\n{1,2} *--/gi, "\n--")
			.replace(/^ */gi, "")
			.replace(/\{comma\}/gi, ",") //换回之前的逗号
			.replace(/UNIONALLALL/gi, "UNION ALL")
			.replace(/(\s|\n){1,};(\n|\s){0,}/gi, "\n;\n\n")
			.replace(/\nUNION ALL\n/gi, "\n\nUNION ALL\n\n")
			.replace(/\nUNION\n/gi, "\n\nUNION\n\n")
			.replace(/\nINTERSECT\n/gi, "\n\nINTERSECT\n\n")
			.replace(/\nEXCEPT\n/gi, "\n\nEXCEPT\n\n")
			.replace(/\n{3,}/gi, "\n\n")
			.replace(/shouldhavenbehind\n/gi, "\n")
			.replace(/shouldhavenbehind/gi, "\n")
			// 恢复注释占位符（顺序：行注释换行标记 -> 行注释 -> 块注释）
			.replace(/NLMARKER\n/gi, "\n")
			.replace(/NLMARKER /gi, "\n")
			.replace(/NLMARKER/gi, "\n")
			.replace(/COMMENTPLACEHOLDER(\d+)/g, function (m, n) {
				return comment_list[Number(n)] !== undefined
					? comment_list[Number(n)]
					: m;
			})
			.replace(/COMMENTBLOCK(\d+)/g, function (m, n) {
				return comment_list[Number(n)] !== undefined
					? comment_list[Number(n)]
					: m;
			})
	);
}

//辅助函数，定位正确的comment
/**
 * Locate the position of the real `--` comment start in a line, ignoring
 * "--" that appears inside brackets or inside string literals.
 *
 * @param {string} text - A single line of SQL.
 * @returns {number} Index of the comment marker (position of the 2nd "-").
 */
function return_right_comment_loc(text) {
	var bracket_cnt = 0;
	var last_char = "";
	var quote_cnt = 0;
	var final_loc = 0;

	for (let i = 0; i < text.length; i++) {
		let p = i;
		if (text[p] == "(" && quote_cnt == 0) {
			bracket_cnt += 1;
		}

		if (text[p] == '"' || text[p] == "'") {
			if (quote_cnt == 0) {
				quote_cnt += 1;
			} else {
				quote_cnt -= 1;
			}
		}

		if (text[p] == ")" && quote_cnt == 0) {
			if (bracket_cnt > 0) {
				bracket_cnt -= 1;
			}
		}

		if (
			bracket_cnt == 0 &&
			quote_cnt == 0 &&
			text[p] == "-" &&
			last_char == "-"
		) {
			break;
		}

		last_char = text[p];
		final_loc = i;
	}

	return final_loc;
}

//遍历替换逻辑
/**
 * Replace every quoted string literal in the text with the placeholder
 * "NEEDReplace", pushing the original literal onto the global restore_list so
 * it can be restored later by restore_strmark(). Recurses until no quote
 * pairs remain, so quoted content is protected from keyword replacements.
 *
 * @param {string} text - Text whose literals should be protected.
 * @returns {string} Text with all literals replaced by "NEEDReplace".
 */
function repeat_text_replace(text) {
	var quote_cnt = 0;
	var quote_tag = "";
	var start_loc = 0;
	var end_loc = 0;
	for (let p = 0; p < text.length; p++) {
		if (text[p] == '"' || text[p] == "'") {
			if (quote_cnt == 0) {
				quote_cnt += 1;
				quote_tag = text[p]; // 需要对起始符号标记类型
				start_loc = p;
			} else {
				if (text[p] == quote_tag) {
					//命中处理逻辑
					quote_cnt -= 1;
					end_loc = p;
					//提取p和q
					modify_line =
						text.slice(0, start_loc) + "NEEDReplace" + text.slice(end_loc + 1);
					restore_list.push(text.slice(start_loc, end_loc + 1));
					return repeat_text_replace(modify_line);
				}
			}
		}
	}
	return text;
}

/**
 * Protect all quoted string literals line by line (respecting `--` comments:
 * only the part before the comment is processed), so that formatting
 * replacements cannot corrupt literal content. The protected literals are
 * restored at the end of the pipeline.
 *
 * @param {string} str - Text to protect.
 * @returns {string} Text with literals replaced by "NEEDReplace" placeholders.
 */
function extract_quotation_mark(str) {
	text_list_orginal = str.split("\n");
	var text_final = "";
	for (let i = 0; i < text_list_orginal.length; i++) {
		var this_line = text_list_orginal[i];

		//假如有评论?,只需处理评论前一段的东西
		var is_comment = this_line.indexOf("--");
		if (is_comment >= 0) {
			comment_loc = return_right_comment_loc(this_line);
			var line_fisrt = this_line.slice(0, comment_loc);
			var line_last = this_line.slice(comment_loc);
			text_final += repeat_text_replace(line_fisrt) + line_last + "\n";
		} else {
			text_final += repeat_text_replace(this_line) + "\n";
		}
	}
	return text_final;
}

/**
 * Restore the original string literals that were protected by
 * extract_quotation_mark() / repeat_text_replace(): each "NEEDReplace"
 * placeholder is replaced by the next entry of the global restore_list.
 * Clears the global state when done.
 *
 * @param {string} str - Text containing "NEEDReplace" placeholders.
 * @returns {string} Text with the original literals restored.
 */
function restore_strmark(str) {
	var replace_loc = str.indexOf("NEEDReplace");
	if (replace_loc >= 0) {
		modify_line =
			str.slice(0, replace_loc) +
			restore_list[restore_cnt] +
			str.slice(replace_loc + 11);
		restore_cnt += 1;
		return restore_strmark(modify_line);
	} else {
		restore_list = [];
		restore_cnt = 0;
		return str;
	}
}

/**
 * Run the full formatting pipeline over the given SQL text:
 * 1. reshape_comment - protect comment keywords
 * 2. replace_char - normalize spacing and keyword line breaks
 * 3. get_bracket - put brackets on their own lines
 * 4. except_subquery - collapse IN (...) subqueries
 * 5. special_wrap - format SELECT / GROUP BY / WHERE clauses
 * 6. bracket_deep - apply indentation
 * 7. extra - final cleanup and placeholder restoration
 *
 * @param {string} text - Raw SQL text.
 * @returns {string} Formatted SQL text.
 */
function newsql(text) {
	step1 = reshape_comment(text);
	step2 = replace_char(step1);
	step3 = get_bracket(step2);
	step4 = except_subquery(step3)
		.replace(/\{\.\*\.\*\}/gi, "(") //复原之前修改的注释后中文()的项目
		.replace(/\{\*\.\*\.\}/gi, ")");

	step5 = special_wrap(step4)
		.replace(/\-\-\s{0,}\n/gi, "\n-- ")
		.replace(/--\{\}/gi, "\n--");
	// console.log(step5);
	step6 = bracket_deep(step5); //union all需要单独函数来考虑
	step7 = extra(step6);
	return step7;
}

/**
 * Extract a column-level DDL from an INSERT statement: format the statement
 * first, then walk each line and derive a column definition from its last
 * token. Lines containing `--` comments become `BIGINT COMMENT "<comment>"`
 * columns; other lines get an empty comment. The result is passed through
 * ddl() to produce an aligned CREATE TABLE body.
 *
 * @param {string} str - Raw INSERT SQL text.
 * @returns {string} Extracted DDL with one BIGINT column per line.
 */
function extractddl(str) {
	str = newsql(str).replace(/\n\s{0,}WHEN/gi, " WHEN");

	var text_final = "";

	var text_list = str.split("\n");
	for (let i = 0; i < text_list.length; i++) {
		text_elmt = text_list[i]
			.trim()
			.replace(/\s{1,}/gi, " ")
			.replace(/\./gi, " ");
		// 判断是否有注释
		var comment_loc = text_elmt.indexOf("--");
		if (comment_loc > 0 && text_elmt.indexOf("FROM") == -1) {
			var as_text = text_elmt.slice(0, comment_loc);
			var comment_text = text_elmt.slice(comment_loc).replace(/-/gi, "").trim();
			var test_list_list = as_text
				.trim()
				.replace(/\s{1,}/gi, " ")
				.split(" ");
			text_final +=
				test_list_list[test_list_list.length - 1] +
				' BIGINT COMMENT "' +
				comment_text +
				'"\n';
		} else if (text_elmt.indexOf("FROM") == -1) {
			var test_list_list = text_elmt.split(" ");
			text_final +=
				test_list_list[test_list_list.length - 1] + ' BIGINT COMMENT " "\n';
		}
	}
	text_final = "     " + ddl(text_final).trim();
	return text_final;
}

/**
 * Convert SQL keywords back to lowercase. Only used when the user disables
 * the `uppercase` option. A comprehensive list of keyword replacements is
 * applied; comments and literals were already protected before this stage.
 *
 * @param {string} str - Uppercase-formatted SQL text.
 * @returns {string} Text with keywords in lowercase.
 */
function convert_lowercase(str) {
	return str
		.replace(/ AND /gi, " and ")
		.replace(/\nAND /gi, "\nand ")
		.replace(/\tAND /gi, "\tand ")
		.replace(/THEN /gi, "then ")
		.replace(/ALTER /gi, "alter ")
		.replace(/OVERWRITE /gi, "overwrite ")
		.replace(/WHEN /gi, "when ")
		.replace(/ELSE /gi, "else ")
		.replace(/ END /gi, " end ")
		.replace(/INSERT/gi, "insert")
		.replace(/INSERT INTO/gi, "insert into")
		.replace(/BETWEEN /gi, "between ")
		.replace(/CASE WHEN/gi, "case when")
		.replace(/DATEDIFF\(/gi, "datediff(")
		.replace(/CEIL\(/gi, "ceil(")
		.replace(/FLOOR\(/g, "floor(")
		.replace(/FROM /gi, "from ")
		.replace(/\nFROM\n/gi, "\nfrom\n")
		.replace(/\tFROM\n/gi, "\tfrom\n")
		.replace(/\tFROM\t/gi, "\tfrom\t")
		.replace(/JOIN /gi, "join ")
		.replace(/\nJOIN\n/gi, "\njoin\n")
		.replace(/DISTRIBUTE BY /gi, "distribute by ")
		.replace(/ AS/gi, " as")
		.replace(/TABLE /gi, "table ")
		.replace(/IF EXISTS/gi, "if exists")
		.replace(/HAVING /gi, "having ")
		.replace(/USING /gi, "using ")
		.replace(/IN /g, "in ")
		.replace(/ NOT IN\n/g, " not in\n") // IN 列表换行后的行尾 NOT IN
		.replace(/\bIN\n/g, " in\n") // IN 列表换行后的行尾 IN
		.replace(/SELECT/gi, "select")
		.replace(/WHERE/gi, "where")
		.replace(/ON /gi, "on ")
		.replace(/CROSS JOIN /gi, "cross join ")
		.replace(/\nCROSS JOIN\n/gi, "\ncross join\n")
		.replace(/INNER JOIN /gi, "inner join ")
		.replace(/\nINNER JOIN\n/gi, "\ninner join\n")
		.replace(/LEFT JOIN /gi, "left join ")
		.replace(/\nLEFT JOIN\n/gi, "\nleft join\n")
		.replace(/\tLEFT JOIN\n/gi, "\tleft join\n")
		.replace(/\tLEFT JOIN\t/gi, "\tleft join\t")
		.replace(/RIGHT JOIN /gi, "right join ")
		.replace(/\nRIGHT JOIN\n/gi, "\nright join\n")
		.replace(/\tRIGHT JOIN\n/gi, "\tright join\n")
		.replace(/\tRIGHT JOIN\t/gi, "\tright join\t")
		.replace(/ORDER BY /gi, "order by ")
		.replace(/GROUP BY /gi, "group by ")
		.replace(/GROUPING SETS/gi, "grouping sets")
		.replace(/UNION ALL/gi, "union all")
		.replace(/UNION /gi, "union ")
		.replace(/UNION\n/gi, "union\n")
		.replace(/LEFT OUTER JOIN /gi, "left outer join ")
		.replace(/\nLEFT OUTER JOIN\n/gi, "\nleft outer join\n")
		.replace(/\tLEFT OUTER JOIN\t/gi, "\tleft outer join\t")
		.replace(/\tLEFT OUTER JOIN\n/gi, "\tleft outer join\n")
		.replace(/RIGHT OUTER JOIN /gi, "right outer join ")
		.replace(/\nRIGHT OUTER JOIN\n/gi, "\nright outer join\n")
		.replace(/\tRIGHT OUTER JOIN\n/gi, "\tright outer join\n")
		.replace(/\tRIGHT OUTER JOIN\t/gi, "\tright outer join\t")
		.replace(/FULL OUTER JOIN /gi, "full outer join ")
		.replace(/\nFULL OUTER JOIN\n/gi, "\nfull outer join\n")
		.replace(/\tFULL OUTER JOIN\t/gi, "\tfull outer join\t")
		.replace(/\tFULL OUTER JOIN\n/gi, "\tfull outer join\n")
		.replace(/FULL JOIN /gi, "full join ")
		.replace(/\nFULL JOIN\n/gi, "\nfull join\n")
		.replace(/\tFULL JOIN\n/gi, "\tfull join\n")
		.replace(/\tFULL JOIN\t/gi, "\tfull join\t")
		.replace(/DROP /gi, "drop ")
		.replace(/CREATE/gi, "create")
		.replace(/SET/gi, "set")
		.replace(/MAX\(/gi, "max(")
		.replace(/MIN\(/gi, "min(")
		.replace(/SUM\(/gi, "sum(")
		.replace(/AVG\(/gi, "avg(")
		.replace(/COUNT\(/gi, "count(")
		.replace(/LIMIT/gi, "limit")
		.replace(/LATERAL VIEW explode/gi, "lateral view explode")
		.replace(/ NOT IN /gi, " not in ")
		.replace(/ LIKE /gi, " like ")
		.replace(/ OVER /gi, " over ")
		.replace(/ PARTITION BY /gi, " partition by ")
		.replace(/\(PARTITION BY /gi, "(partition by ")
		.replace(/row_number /gi, "row_number ")
		.replace(/row_number\(/gi, "row_number(")
		.replace(/ asc /gi, " asc ")
		.replace(/ desc /gi, " desc ");
}

/**
 * Move the comma of each column pair to the end of the previous line
 * (comma-last style) instead of the start of the next line. Comment lines are
 * handled specially so the comment text stays with the column. Only applied
 * when the user enables the `comma_location` option.
 *
 * @param {string} str - Formatted SQL text with commas at line starts.
 * @returns {string} Text with commas moved to the end of lines.
 */
function convert_comma_loaction(str) {
	var text_final = "";
	var text_list = str.replace(/\n *\-\-/gi, " \-\-{}").split("\n");
	for (let i = 0; i < text_list.length; i++) {
		this_line = text_list[i];

		if (i + 1 <= text_list.length) {
			next_line = text_list[i + 1];
		} else {
			next_line = "";
		}

		//判断this line是否有评论
		is_comment = this_line.indexOf("--");
		if (is_comment >= 0) {
			comment_loc = return_right_comment_loc(this_line);
		}

		//针对本行，如果有逗号，先剔除
		if (/^\s+\,/.exec(this_line)) {
			var the_comma_loc = this_line.indexOf(",");
			this_line =
				this_line.slice(0, the_comma_loc) +
				" " +
				this_line.slice(the_comma_loc + 1);
		}

		this_line.replace(/\s$/gi, "") + "," + "\n ";

		if (/^\s+\,/.exec(next_line)) {
			if (is_comment > 0) {
				//如果有comment可以调整逗号位置
				text_final +=
					this_line.slice(0, comment_loc).replace(/\s$/gi, "") +
					"," +
					this_line.slice(comment_loc) +
					"\n";
			} else {
				text_final += this_line.replace(/\s$/gi, "") + "," + "\n";
			}
		} else {
			text_final += this_line + "\n";
		}
	}
	return text_final.replace(/\-\-\{\}/gi, "\n--");
}

/**
 * Align `--` comments: compute the widest comment position (up to 125 chars)
 * and pad every shorter line with spaces so that all comments start at the
 * same column. Lines whose code part is >= 126 chars get the comment pushed
 * to a new line instead.
 *
 * @param {string} str - Formatted text containing ` --` comments.
 * @returns {string} Text with aligned comment columns.
 */
function order_comment(str) {
	final_text = "";
	var text_list = str.split("\n");
	var max_comment_loc = 0;
	for (let i = 0; i < text_list.length; i++) {
		var comment_loc = text_list[i].indexOf(" --");
		if (comment_loc > max_comment_loc && comment_loc < 126) {
			max_comment_loc = comment_loc;
		}
	}

	for (let i = 0; i < text_list.length; i++) {
		segment = text_list[i].split(" --");
		if (segment.length > 1 && segment[0].length < 126) {
			num = max_comment_loc + 2 - segment[0].length;
			for (let j = 0; j < num; j++) {
				segment[0] = segment[0] + " ";
			}
			segment[0] = segment[0] + "--" + segment[1];
		} else if (segment.length > 1 && segment[0].length >= 126) {
			segment[0] += "\n";
			num = max_comment_loc + 2;
			for (let j = 0; j < num; j++) {
				segment[0] = segment[0] + " ";
			}
			segment[0] = segment[0] + "--" + segment[1];
		}
		final_text += segment[0] + "\n";
	}
	return final_text;
}
// and 与 on 与 where 等主要选择性字符不同，将where后面的and增加缩进
/**
 * Indent lines that start with "and " (i.e. WHERE conditions) by 6 spaces so
 * they are visually distinguished from the WHERE keyword itself.
 *
 * @param {string} str - Formatted text.
 * @returns {string} Text with WHERE-condition AND lines indented.
 */
function order_where(str) {
	final_text = "";
	var text_list = str.split("\n");

	for (let i = 0; i < text_list.length; i++) {
		sen = text_list[i];
		loc = sen.indexOf("and ");

		if (loc != -1 && loc < 2) {
			sen = sen.replace("and ", "      and ");
		}
		final_text = final_text + sen + "\n";
	}
	return final_text;
}
// 将where后面的on增加缩进
/**
 * Indent lines that start with "on " (i.e. JOIN conditions) by 5 spaces so
 * they are visually distinguished from the JOIN keyword itself.
 *
 * @param {string} str - Formatted text.
 * @returns {string} Text with JOIN-condition ON lines indented.
 */
function order_on(str) {
	final_text = "";
	var text_list = str.split("\n");

	for (let i = 0; i < text_list.length; i++) {
		sen = text_list[i];
		loc = sen.indexOf("on ");

		if (loc != -1 && loc < 2) {
			sen = sen.replace("on ", "     on ");
		}
		if (sen != "") {
			final_text = final_text + sen + "\n";
		}
	}
	return final_text;
}

/**
 * Public API: beautify SQL text according to the user configuration.
 * Runs the main pipeline (quotation protection -> reshape_comment ->
 * replace_char -> get_bracket -> except_subquery -> special_wrap ->
 * bracket_deep -> extra) and combines the resulting steps based on the
 * combination of the uppercase / comma_location / bracket_char flags:
 * uppercase=false additionally applies convert_lowercase() and the
 * order_comment / order_where / order_on alignment steps; comma_location=true
 * applies convert_comma_loaction(); bracket_char=true replaces tabs with
 * four spaces.
 *
 * @param {string} text - Raw SQL text to beautify.
 * @param {boolean} uppercase - Convert keywords to uppercase (true) or lowercase (false).
 * @param {boolean} comma_location - Put commas at the end of lines.
 * @param {boolean} bracket_char - Use 4 spaces instead of tabs for indentation.
 * @param {number} as_loc_cnt - Max column length participating in AS alignment.
 * @param {number} [in_wrap_length] - Max formatted line length before an IN
 *        list is wrapped one item per line; <= 0 disables (defaults to 150).
 * @returns {string} Beautified SQL text.
 */
vkbeautify.prototype.sql = function (
	text,
	uppercase,
	comma_location,
	bracket_char,
	as_loc_cnt,
	in_wrap_length,
) {
	if (in_wrap_length === undefined) {
		in_wrap_length = IN_WRAP_LENGTH_DEFAULT;
	}
	restore_list = [];
	restore_cnt = 0;

	step0 = extract_quotation_mark(text);
	step1 = reshape_comment(step0);
	step2 = replace_char(step1);
	step2u = uppercase_keywords(step2); //关键字表驱动的统一大写遍历
	step3 = get_bracket(step2u);
	step4 = except_subquery(step3)
		.replace(/\{\.\*\.\*\}/gi, "(") //复原之前修改的注释后中文()的项目
		.replace(/\{\*\.\*\.\}/gi, ")");
	// step5 = special_wrap(step4).replace(/\-\-\s{0,}\n/ig, "\n-- ");
	step5 = special_wrap(step4, as_loc_cnt).replace(/\s{0,1}--{}/gi, "\n--");
	// console.log(step5);
	step6 = bracket_deep(step5); //union all需要单独函数来考虑
	step65 = in_wrap(step6, in_wrap_length, comma_location); //超长 IN 列表按逗号换行
	step66 = over_wrap(step65, in_wrap_length); //超长 OVER 子句按窗口子句换行
	step67 = condition_wrap(step66, in_wrap_length); //超长括号条件组按连接词换行
	step7 = extra(step67);
	step8 = restore_strmark(step7);
	step9 = convert_lowercase(step8); //转换小写
	step10 = order_comment(step9); //排序评论
	step11 = order_where(step10); //排序where后面条件
	step12 = order_on(step11); //排序on条件

	if (uppercase == true && comma_location == true && bracket_char == false) {
		return convert_comma_loaction(step8);
	} else if (
		uppercase == true &&
		comma_location == true &&
		bracket_char == true
	) {
		return convert_comma_loaction(step8).replace(/\t/gi, "    "); //用四个空格替换
	} else if (
		uppercase == true &&
		comma_location == false &&
		bracket_char == false
	) {
		return step8;
	} else if (
		uppercase == true &&
		comma_location == false &&
		bracket_char == true
	) {
		return step8.replace(/\t/gi, "    ");
	} else if (
		uppercase == false &&
		comma_location == true &&
		bracket_char == false
	) {
		return convert_comma_loaction(step9);
	} else if (
		uppercase == false &&
		comma_location == true &&
		bracket_char == true
	) {
		return convert_comma_loaction(step9).replace(/\t/gi, "    "); //用四个空格替换
	} else if (
		uppercase == false &&
		comma_location == false &&
		bracket_char == false
	) {
		return step12;
	} else if (
		uppercase == false &&
		comma_location == false &&
		bracket_char == true
	) {
		return step12.replace(/\t/gi, "    ");
	}
};

/**
 * Public API: beautify a Hive DDL statement. CREATE [EXTERNAL/TEMPORARY]
 * TABLE statements are aligned via ddl(); CREATE VIEW statements are
 * delegated to the main SQL pipeline; other DDL (ALTER / DROP / TRUNCATE) is
 * normalized by ddl_simple().
 *
 * @param {string} text - Raw DDL text.
 * @returns {string} Beautified DDL text.
 */
vkbeautify.prototype.sqlddl = function (text) {
	if (/^\s*create\s+view\b/i.test(text)) {
		return vkbeautify.prototype.sql.call(
			this,
			text,
			true,
			false,
			true,
			150,
			IN_WRAP_LENGTH_DEFAULT,
		);
	}
	if (/^\s*create\s+(external\s+|temporary\s+)?table\b/i.test(text)) {
		return ddl(text);
	}
	return ddl_simple(text);
};

/**
 * Public API: extract a column DDL from an INSERT statement.
 *
 * @param {string} text - Raw INSERT SQL text.
 * @returns {string} Extracted DDL.
 */
vkbeautify.prototype.extractddl = function (text) {
	return extractddl(text);
};

module.exports = new vkbeautify();
